const updateShare = `-- name: UpdateShare :one
UPDATE shares
SET slug = ?1,
    password_hash = ?2,
    expires_at = ?3,
    max_downloads = ?4,
    allow_download = ?5,
    allow_upload = ?6,
    hide_owner = ?7,
    hide_listing = ?8,
    note = ?9,
    updated_at = ?10
WHERE id = ?11 AND owner_user_id = ?12
RETURNING id, owner_user_id, path, is_dir, mode, token_hash, slug, password_hash, expires_at, max_downloads, download_count, view_count, allow_download, allow_upload, allow_reshare, hide_owner, hide_listing, note, token_enc, disabled_at, disabled_reason, broken_at, last_access_at, created_at, updated_at
`

type UpdateShareParams struct {
	Slug          *string `json:"slug"`
	PasswordHash  *string `json:"password_hash"`
	ExpiresAt     *string `json:"expires_at"`
	MaxDownloads  *int64  `json:"max_downloads"`
	AllowDownload int64   `json:"allow_download"`
	AllowUpload   int64   `json:"allow_upload"`
	HideOwner     int64   `json:"hide_owner"`
	HideListing   int64   `json:"hide_listing"`
	Note          *string `json:"note"`
	UpdatedAt     string  `json:"updated_at"`
	ID            string  `json:"id"`
	OwnerUserID   string  `json:"owner_user_id"`
}

func (q *Queries) UpdateShare(ctx context.Context, arg UpdateShareParams) (Share, error) {
	row := q.db.QueryRowContext(ctx, updateShare,
		arg.Slug,
		arg.PasswordHash,
		arg.ExpiresAt,
		arg.MaxDownloads,
		arg.AllowDownload,
		arg.AllowUpload,
		arg.HideOwner,
		arg.HideListing,
		arg.Note,
		arg.UpdatedAt,
		arg.ID,
		arg.OwnerUserID,
	)
	var i Share
	err := row.Scan(
		&i.ID,
		&i.OwnerUserID,
		&i.Path,
		&i.IsDir,
		&i.Mode,
		&i.TokenHash,
		&i.Slug,
		&i.PasswordHash,
		&i.ExpiresAt,
		&i.MaxDownloads,
		&i.DownloadCount,
		&i.ViewCount,
		&i.AllowDownload,
		&i.AllowUpload,
		&i.AllowReshare,
		&i.HideOwner,
		&i.HideListing,
		&i.Note,
		&i.TokenEnc,
		&i.DisabledAt,
		&i.DisabledReason,
		&i.BrokenAt,
		&i.LastAccessAt,
		&i.CreatedAt,
		&i.UpdatedAt,
	)
	return i, err
}
